package com.aivle.backend.journey;
import com.aivle.backend.common.entity.BaseEntity;import com.aivle.backend.project.entity.Project;import com.aivle.backend.taskrun.domain.TaskRun;import jakarta.persistence.*;import java.time.LocalDateTime;import lombok.*;
@Entity(name="JourneyFinalReport") @Table(name="final_reports") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class JourneyFinalReport extends BaseEntity{public enum State{PENDING,RUNNING,SUCCEEDED,FAILED}public enum Decision{GO,CONDITIONAL_GO,REWORK,HOLD,STOP}@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="project_id",nullable=false)private Project project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="idea_version_id",nullable=false)private IdeaVersion ideaVersion;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="concept_version_id",nullable=false)private ConceptVersion conceptVersion;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="workspace_id",nullable=false)private JourneyMarketingWorkspace workspace;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="task_run_id")private TaskRun taskRun;@Column(name="source_reference_json",nullable=false,columnDefinition="TEXT")private String sourceReferenceJson;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private State state;@Enumerated(EnumType.STRING)@Column(name="ai_decision",length=30)private Decision aiDecision;@Enumerated(EnumType.STRING)@Column(name="user_decision",length=30)private Decision userDecision;@Column(name="user_decision_reasons_json",columnDefinition="TEXT")private String userDecisionReasonsJson;@Column(name="result_json",columnDefinition="TEXT")private String resultJson;@Column(length=100)private String error;private LocalDateTime completedAt;public static JourneyFinalReport pending(Project p,IdeaVersion i,ConceptVersion c,JourneyMarketingWorkspace w,String source){JourneyFinalReport v=new JourneyFinalReport();v.project=p;v.ideaVersion=i;v.conceptVersion=c;v.workspace=w;v.sourceReferenceJson=source;v.state=State.PENDING;return v;}public void start(TaskRun t){taskRun=t;state=State.RUNNING;resultJson=null;error=null;completedAt=null;}public void succeed(Decision d,String result){aiDecision=d;resultJson=result;state=State.SUCCEEDED;error=null;completedAt=LocalDateTime.now();}public void fail(String e){state=State.FAILED;error=e;completedAt=LocalDateTime.now();}public void decide(Decision d,String reasons){userDecision=d;userDecisionReasonsJson=reasons;}}
